components.css:
.ds-tile { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 0.25rem; width: 160px; min-height: 112px; margin: 4px; padding: 0.75rem; border: 1px solid #D9DEE3; border-radius: 0.75rem; background: #FFFFFF; color: #1F2328; text-align: left; cursor: pointer; font-family: Roboto, Nokora, sans-serif; }
.ds-tile__stripe { position: absolute; inset: 0 0 auto 0; display: flex; height: 3px; overflow: hidden; border-radius: 0.75rem 0.75rem 0 0; }
.ds-tile__stripe i { flex: 1; }
.ds-tile__dots { position: absolute; right: 0.75rem; top: 0.75rem; display: inline-flex; mix-blend-mode: multiply; }
.ds-tile__dots i { width: 10px; height: 10px; border-radius: 9999px; box-shadow: 0 1px 3px rgb(0 0 0 / 0.25), inset 0 -1px 0 rgb(0 0 0 / 0.15); }
.ds-tile__name { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-top: 0.5rem; font-size: 0.875rem; font-weight: 500; }
.ds-tile__price { margin-top: auto; font-size: 1.875rem; font-weight: 900; line-height: 1.1; font-variant-numeric: tabular-nums; }
.ds-tile__meta { font-size: 0.75rem; font-weight: 500; letter-spacing: 0.02em; line-height: 1.6; color: hsl(215 16% 38%); }
.ds-tile:hover { border-color: hsl(215 16% 38% / 0.4); }
.ds-tile:active { transform: scale(0.98); }
.ds-tile:focus-visible { outline: 2px solid #1F2328; outline-offset: 2px; }

.ds-btn { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; height: 36px; padding: 0 0.75rem; border-radius: 0.375rem; font-family: Roboto, Nokora, sans-serif; font-size: 0.875rem; font-weight: 500; line-height: 1.25; cursor: pointer; transition: background-color .15s, color .15s, box-shadow .15s; border: none; margin-right: 0.5rem; }
.ds-btn--default { background: #1F2328; color: #FFFFFF; }
.ds-btn--default:hover { background: rgb(31 35 40 / 0.9); }
.ds-btn--commit { background: #D97B2A; color: #1F2328; font-weight: 600; }
.ds-btn--commit:hover { box-shadow: inset 0 -3px 0 #C46D22; }
.ds-btn--commit:active { background: #C46D22; }
.ds-btn--commit-outline { border: 1px solid #C46D22; background: rgb(217 123 42 / 0.1); color: #1F2328; }
.ds-btn--commit-outline:hover { background: rgb(217 123 42 / 0.25); }
.ds-btn:focus-visible { outline: 2px solid #1F2328; outline-offset: 2px; }

.ds-board-header { padding-bottom: 0.75rem; border-bottom: 2px solid #1F2328; font-family: Roboto, Nokora, sans-serif; color: #1F2328; }
.ds-board-header__top { display: flex; justify-content: space-between; align-items: baseline; font-size: 0.75rem; font-weight: 500; letter-spacing: 0.02em; line-height: 1.6; color: hsl(215 16% 38%); }
.ds-board-header__date { text-transform: uppercase; }
.ds-board-header__title { margin: 0.25rem 0 0; font-size: 1.5rem; font-weight: 900; line-height: 1.2; }
.ds-board-header__sub { margin: 0.25rem 0 0; font-size: 0.875rem; color: hsl(215 16% 38%); }

.ds-table { width: 100%; max-width: 560px; border-collapse: separate; border-spacing: 0; border: 1px solid #D9DEE3; border-radius: 0.5rem; overflow: hidden; background: #FFFFFF; color: #1F2328; font-family: Roboto, Nokora, sans-serif; font-size: 0.875rem; }
.ds-table th { padding: 0.375rem 0.75rem; background: #F4F6F8; color: hsl(215 16% 38%); text-align: left; font-size: 0.75rem; font-weight: 500; letter-spacing: 0.02em; line-height: 1.6; }
.ds-table td { padding: 3px 0.75rem; line-height: 17px; border-top: 1px solid #D9DEE3; white-space: nowrap; }
.ds-table td + td, .ds-table th + th { border-left: 1px solid rgb(217 222 227 / 0.6); }
.ds-table tbody tr:hover td { background: #F4F6F8; }
.ds-table .ds-num { text-align: right; font-variant-numeric: tabular-nums; }
.ds-dot { display: inline-block; width: 10px; height: 10px; border-radius: 9999px; box-shadow: 0 1px 3px rgb(0 0 0 / 0.25); vertical-align: middle; }
.ds-magnet-sm { display: inline-block; width: 14px; height: 14px; border-radius: 9999px; box-shadow: 0 1px 3px rgb(0 0 0 / 0.25), inset 0 -1px 0 rgb(0 0 0 / 0.15); }

.ds-side { display: flex; flex-direction: column; gap: 2px; width: 220px; padding: 0.5rem; background: #F4F6F8; border-right: 1px solid #D9DEE3; font-family: Roboto, Nokora, sans-serif; }
.ds-side__group { padding: 0.5rem 0.75rem 0.25rem; font-size: 0.75rem; font-weight: 500; letter-spacing: 0.18em; text-transform: uppercase; color: hsl(215 16% 38%); }
.ds-side__item { display: flex; align-items: center; gap: 0.75rem; padding: 0.5rem 0.75rem; border-radius: 0.375rem; font-size: 0.875rem; font-weight: 500; color: #1F2328; text-decoration: none; }
.ds-side__item--active { background: #FFFFFF; }
.ds-side__item:hover { background: rgb(255 255 255 / 0.6); }
.ds-side__dot { width: 8px; height: 8px; border-radius: 9999px; background: #1F2328; }
.ds-side__dot--off { background: #9CA3AF; }

.ds-slip { width: 405px; padding: 1rem; border: 2px solid #000000; background: #FFFFFF; color: #000000; font-family: Roboto, Nokora, sans-serif; font-size: 0.875rem; line-height: 1.5; text-align: center; }
.ds-slip__shop { font-size: 1.125rem; font-weight: 900; line-height: 1.4; }
.ds-slip__branch { margin-bottom: 0.5rem; }
.ds-slip__qr { width: 150px; height: 150px; margin: 0.5rem auto; background: repeating-conic-gradient(#000 0 25%, #fff 0 50%) 0 0 / 20px 20px; }
.ds-slip__code { font-weight: 700; letter-spacing: 0.08em; }
.ds-slip__date { color: #DC2626; margin-bottom: 0.5rem; }
.ds-slip__row { display: flex; justify-content: space-between; text-align: left; }
.ds-slip__rule { height: 2px; border: none; background: #000000; margin: 0.5rem 0; }
.ds-slip__thanks { margin-top: 0.5rem; font-weight: 700; }
